package android.view;import java.util.*;public class ViewTreeObserver {public interface OnPreDrawListener {boolean onPreDraw();}public interface OnDrawListener{void onDraw();}List<OnPreDrawListener> list=new ArrayList<>();List<OnDrawListener> draws=new ArrayList<>();public void addOnPreDrawListener(OnPreDrawListener l){list.add(l);}public void removeOnPreDrawListener(OnPreDrawListener l){list.remove(l);}public void addOnDrawListener(OnDrawListener l){draws.add(l);}public void removeOnDrawListener(OnDrawListener l){draws.remove(l);}public boolean isAlive(){return true;}public void draw(){for(OnPreDrawListener l:new ArrayList<>(list))l.onPreDraw();for(OnDrawListener l:new ArrayList<>(draws))l.onDraw();}}
